add_filter( 'product_type_selector', 'perfectpixel_only_simple_products' );
add_filter( 'product_type_options', 'perfectpixel_only_simple_product_options' );

function perfectpixel_only_simple_products( $types ) {
	global $post;
	$keep = array( 'simple' );
	// Keep the current type of an existing product, so it is not broken on save.
	$product = $post ? wc_get_product( $post->ID ) : null;
	if ( $product && 'simple' !== $product->get_type() ) {
		$keep[] = $product->get_type();
	}
	return array_intersect_key( $types, array_flip( $keep ) );
}

function perfectpixel_only_simple_product_options( $options ) {
	if ( 'yes' === '{{hide_virtual_downloadable}}' ) {
		unset( $options['virtual'], $options['downloadable'] );
	}
	return $options;
}
